      "proposed_laureates": [
        "Kenneth J. Schafer",
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision model gave strong-field physics a simple, predictive picture and underpins high-harmonic generation and attosecond science, revealing electron motion on its natural timescale.",
        "attribution": "The credited theorists made complementary contributions to the three-step description. The wider experimental and theoretical development of the field makes precise division of credit important.",
        "maturity": "The model has been tested and extended across decades of experiments and has enabled reproducible measurements of ultrafast electronic dynamics.",
        "uncertainties": [
          "The nomination may compress distinct theoretical and experimental contributions into one discovery."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B064",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision measurement and opened tests of fundamental physics with extraordinary sensitivity.",
        "attribution": "Katori and Ye led complementary routes to lattice confinement and high precision; their contributions are central and identifiable.",
        "maturity": "The technology is established across laboratories, with clock comparisons confirming its precision and robustness.",
        "uncertainties": [
          "The field continues to advance rapidly, so the lasting scope of its most consequential fundamental tests is still developing."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric and topological phases show that quantum states carry physically observable structure beyond their energies, with consequences across many areas of physics.",
        "attribution": "Aharonov's work established the physical significance of potentials in the Aharonov–Bohm effect; Berry identified the geometric phase that now bears his name. These are related but distinct contributions.",
        "maturity": "The effects have been confirmed in many systems and are now standard tools in quantum physics.",
        "uncertainties": [
          "The broad label combines discoveries from different periods and may omit other important contributors to their experimental establishment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled studies of strongly correlated quantum matter possible and created a powerful bridge between theory and experiment.",
        "attribution": "Bloch's experiments and Cirac and Zoller's theoretical work on quantum simulation are major contributions. The credited list also includes other pioneers of the first demonstrations, so a three-person award would require careful delimitation.",
        "maturity": "The platform has produced reproducible results across many groups and continues to grow in experimental control and scientific reach.",
        "uncertainties": [
          "The boundary between foundational quantum simulation and later platform-specific advances is not sharp."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Harald Rose",
        "Maximilian Haider",
        "Ondrej L. Krivanek"
      ],
      "assessment": {
        "nobel_worthiness": "Correcting electron-optical aberrations removed a major limit on microscopy and enabled direct structural study at atomic scales.",
        "attribution": "Rose's theory and the instrumental advances of Haider and Krivanek form a compelling theory-to-device contribution, though the history includes broader engineering teams.",
        "maturity": "Aberration-corrected instruments are established and have enabled reproducible results across materials science and microscopy.",
        "uncertainties": [
          "The specific scope of the credited contribution—corrector design, implementation, or resulting microscopy—needs clear definition."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "SASE made bright, coherent X-ray pulses available on femtosecond timescales, opening access to atomic-scale dynamics and extreme states of matter.",
        "attribution": "Pellegrini, Kim, and Rossbach are associated with key theoretical and accelerator developments. Construction and operation also depended on substantial teams.",
        "maturity": "Multiple operating facilities have established the method as a reliable source for a wide range of experiments.",
        "uncertainties": [
          "The relative credit for the core SASE concept, its accelerator realization, and the first working facility is difficult to allocate."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B051",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how fragile quantum information can in principle be protected, providing a crucial foundation for quantum computation.",
        "attribution": "Shor and Steane developed influential early codes, while Kitaev established deep connections to topological codes and fault tolerance. The credited set spans related but distinct advances.",
        "maturity": "The theory is robust and has guided experimental progress, although scalable fault-tolerant computation remains an active challenge.",
        "uncertainties": [
          "The award scope would need to distinguish foundational theory from later developments and implementations."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Programmable neutral-atom arrays have become a striking route to controlled many-body physics and quantum information, with rapidly expanding capabilities.",
        "attribution": "Browaeys, Saffman, and Lukin represent important experimental and conceptual contributions, but the field involves several groups and parallel advances.",
        "maturity": "The platform has produced impressive demonstrations, but its long-term scientific reach and reliability at larger scales are still being established.",
        "uncertainties": [
          "The field is young, and it is not yet clear which achievements will prove most durable."
        ]
      }
    }
  ]
